import { useMemo, useState } from "react";

type LivePlatform = "douyin" | "kuaishou";
type AccountStatus = "bound" | "unbound" | "expired";

type AudioDevice = {
  id: string;
  name: string;
  desc: string;
};

const audioDevices: AudioDevice[] = [
  {
    id: "vb-cable",
    name: "VB-Cable",
    desc: "推荐，用于直播间声音输出",
  },
  {
    id: "system-default",
    name: "系统默认声卡",
    desc: "适合本地预览",
  },
  {
    id: "none",
    name: "暂不输出声音",
    desc: "仅输出画面",
  },
];

