  douyin: "抖音",
  kuaishou: "快手",
};

const accountCopy: Record<AccountStatus, string> = {
  bound: "已绑定",
  unbound: "未绑定",
  expired: "已过期",
};

export default function SettingsPage() {
  const [virtualCameraEnabled, setVirtualCameraEnabled] = useState(true);
  const [audioDevice, setAudioDevice] = useState("vb-cable");
  const [platform, setPlatform] = useState<LivePlatform>("douyin");
  const [accountStatus, setAccountStatus] = useState<AccountStatus>("unbound");

  const readyScore = useMemo(() => {
    let score = 0;

    if (virtualCameraEnabled) score += 1;
    if (audioDevice !== "none") score += 1;
    if (platform) score += 1;
    if (accountStatus === "bound") score += 1;

    return score;
  }, [virtualCameraEnabled, audioDevice, platform, accountStatus]);

  const readyText =
    readyScore >= 4
      ? "已准备好开播"
      : readyScore >= 2
        ? "还差一点配置"
        : "需要先完成基础设置";

  const selectedAudio = audioDevices.find((item) => item.id === audioDevice);

  return (
    <section className="settings-page">
      <style>{styles}</style>

      <div className="settings-hero">
        <div>
          <p className="eyebrow">Simple Settings</p>
          <h2>开播前，只确认这几项就够了。</h2>
          <p>
            PHS 会把画面和声音自动送到直播工具。你只需要选择平台、确认账号状态，并打开画面输出。
          </p>
        </div>

        <div className="ready-card">
          <div className={`ready-ring level-${readyScore}`}>
            <span>{readyScore}/4</span>
          </div>
          <strong>{readyText}</strong>
          <small>
            当前平台：{platformCopy[platform]} · 声音：{selectedAudio?.name}
          </small>
        </div>
      </div>

      <div className="settings-grid">
        <div className="setting-card primary-card">
          <div className="setting-main">
            <div>
              <p className="eyebrow">Video Output</p>
              <h3>虚拟摄像头</h3>
              <p>开启后，PHS 会把直播画面输出到开播工具。</p>
            </div>

            <button
              type="button"
              className={`switch ${virtualCameraEnabled ? "on" : ""}`}
              onClick={() => setVirtualCameraEnabled((value) => !value)}
              aria-pressed={virtualCameraEnabled}
            >
              <span />
            </button>
          </div>

          <div className="device-preview">
            <div className="preview-screen">
              <span className={virtualCameraEnabled ? "signal on" : "signal"} />
              <strong>{virtualCameraEnabled ? "画面输出已开启" : "画面输出已关闭"}</strong>
              <small>{virtualCameraEnabled ? "开播工具可读取 PHS 画面" : "开启后即可输出直播画面"}</small>
            </div>
          </div>
        </div>

        <div className="setting-card">
          <p className="eyebrow">Audio Output</p>
          <h3>声音输出</h3>
          <p>选择直播间使用的声音通道。</p>

          <div className="option-list">
            {audioDevices.map((item) => (
              <button
                key={item.id}
                type="button"
                className={audioDevice === item.id ? "option active" : "option"}
                onClick={() => setAudioDevice(item.id)}
              >
                <span className="option-dot" />
                <span>
                  <strong>{item.name}</strong>
                  <small>{item.desc}</small>
                </span>
              </button>
            ))}
          </div>
        </div>

        <div className="setting-card">
          <p className="eyebrow">Platform</p>
          <h3>直播平台</h3>
          <p>选择本次开播的平台。</p>

          <div className="platform-tabs">
            <button
              type="button"
              className={platform === "douyin" ? "active" : ""}
              onClick={() => setPlatform("douyin")}
            >
              抖音
            </button>
            <button
              type="button"
              className={platform === "kuaishou" ? "active" : ""}
              onClick={() => setPlatform("kuaishou")}
            >
              快手
            </button>
          </div>

          <div className="platform-note">
            <strong>{platformCopy[platform]}直播</strong>
            <span>系统会按当前平台保存开播偏好。</span>
          </div>
        </div>

        <div className="setting-card">
          <p className="eyebrow">Account</p>
          <h3>账号绑定</h3>
          <p>绑定后可以更顺畅地进入开播流程。</p>

          <div className={`account-state ${accountStatus}`}>
            <span />
            <div>
              <strong>{accountCopy[accountStatus]}</strong>
              <small>
                {accountStatus === "bound"
                  ? `${platformCopy[platform]}账号可用`
                  : accountStatus === "expired"
                    ? "账号状态已过期，请重新绑定"
                    : `尚未绑定${platformCopy[platform]}账号`}
              </small>
            </div>
          </div>

          <div className="account-actions">
            {accountStatus !== "bound" ? (
              <button
                type="button"
                className="gold-button"
                onClick={() => setAccountStatus("bound")}
              >
                绑定账号
              </button>
            ) : (
              <button
                type="button"
                className="soft-button"
                onClick={() => setAccountStatus("expired")}
              >
                模拟过期
              </button>
            )}

            {accountStatus !== "unbound" && (
              <button
                type="button"
                className="ghost-button"
                onClick={() => setAccountStatus("unbound")}
              >
                解除绑定
              </button>
            )}
          </div>
        </div>
      </div>
    </section>
  );
}

