import { Dispatch, SetStateAction, useEffect, useMemo, useState } from "react";

export type BroadcastAsset = {
  id: string;
  name: string;
  type?: "image" | "video" | "file";
  status?: string;
  previewUrl?: string;
  url?: string;
  thumbnailUrl?: string;
  variants?: number;
};

type BroadcastPageProps = {
  assets?: BroadcastAsset[];
  isLive?: boolean;
  setIsLive?: Dispatch<SetStateAction<boolean>> | ((value: boolean) => void);
  onNeedAssets?: () => void;
};

type TtsStatus = "idle" | "speaking" | "waiting";
type BroadcastStage = "idle" | "starting" | "live" | "stopping";

const demoAssets: BroadcastAsset[] = [
  {
    id: "demo-asset-1",
    name: "默认直播画面 A",
    type: "image",
    status: "ready",
    variants: 6,
  },
  {
    id: "demo-asset-2",
    name: "默认直播画面 B",
    type: "image",
    status: "ready",
    variants: 4,
  },
];

export default function BroadcastPage({
  assets,
  isLive,
  setIsLive,
  onNeedAssets,
}: BroadcastPageProps) {
  const [internalLive, setInternalLive] = useState(false);
  const [stage, setStage] = useState<BroadcastStage>("idle");
  const [activeIndex, setActiveIndex] = useState(0);
  const [liveSeconds, setLiveSeconds] = useState(0);
  const [ttsStatus, setTtsStatus] = useState<TtsStatus>("idle");
  const [commentCount, setCommentCount] = useState(0);

  const controlledLive = typeof isLive === "boolean";
  const live = controlledLive ? Boolean(isLive) : internalLive;

  const updateLive = (value: boolean) => {
    if (setIsLive) {
      setIsLive(value);
    }

    if (!controlledLive) {
      setInternalLive(value);
    }
  };

  const readyAssets = useMemo(() => {
    const source = assets && assets.length > 0 ? assets : demoAssets;
    return source.filter((item) => !item.status || item.status === "ready");
  }, [assets]);

  const activeAsset = readyAssets[activeIndex % Math.max(readyAssets.length, 1)];

  const ttsCopy: Record<TtsStatus, string> = {
    idle: "待播报",
    speaking: "正在播报",
    waiting: "等待下一句",
  };

  const stageText =
    stage === "starting"
      ? "正在准备开播"
      : stage === "stopping"
        ? "正在结束开播"
        : live
          ? "正在开播"
          : readyAssets.length > 0
            ? "随时可开播"
            : "请先上传素材";

  useEffect(() => {
    if (!live) {
      setLiveSeconds(0);
      setTtsStatus("idle");
      return;
    }

    const timer = window.setInterval(() => {
      setLiveSeconds((value) => value + 1);
    }, 1000);

    return () => window.clearInterval(timer);
  }, [live]);

  useEffect(() => {
    if (!live || readyAssets.length <= 1) return;

    const timer = window.setInterval(() => {
      setActiveIndex((index) => (index + 1) % readyAssets.length);
    }, 5200);

    return () => window.clearInterval(timer);
  }, [live, readyAssets.length]);

  useEffect(() => {
    if (!live) return;

    const timer = window.setInterval(() => {
      setTtsStatus((current) => {
        if (current === "idle") return "speaking";
        if (current === "speaking") return "waiting";
        return "speaking";
      });
    }, 3600);

    return () => window.clearInterval(timer);
  }, [live]);

  useEffect(() => {
    if (!live) return;

    const timer = window.setInterval(() => {
      setCommentCount((value) => value + Math.floor(Math.random() * 4));
    }, 2600);

    return () => window.clearInterval(timer);
  }, [live]);

  const handleStart = async () => {
    if (readyAssets.length === 0) {
      onNeedAssets?.();
      return;
    }

    setStage("starting");

    try {
      await fetch("/api/pipeline/run", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          mode: "broadcast",
          assets: readyAssets.map((item) => item.id),
        }),
      });
    } catch {
      // 消费级前端不暴露技术错误，保留本地预览体验。
    }

    window.setTimeout(() => {
      updateLive(true);
      setStage("live");
      setTtsStatus("speaking");
    }, 900);
  };

  const handleStop = async () => {
    setStage("stopping");

    try {
      await fetch("/api/pipeline/stop", {
        method: "POST",
      });
    } catch {
      // 消费级前端不暴露技术错误，保留本地状态切换。
    }

    window.setTimeout(() => {
      updateLive(false);
      setStage("idle");
      setTtsStatus("idle");
    }, 700);
  };

  return (
    <section className="broadcast-page">
      <style>{styles}</style>

      <div className={`broadcast-hero ${live ? "live" : ""}`}>
        <div className="hero-copy">
          <p className="eyebrow">Start Live</p>
