              <button type="button" className="ghost-button big" onClick={onNeedAssets}>
                去上传素材
              </button>
            )}
          </div>
        </div>

        <div className="hero-status">
          <span className={live ? "live-dot on" : "live-dot"} />
          <strong>{stageText}</strong>
          <small>
            {live
              ? `已开播 ${formatDuration(liveSeconds)}`
              : `${readyAssets.length} 个素材可用`}
          </small>
