            <div className="obs-live-word">LIVE</div>

            {activeAsset?.previewUrl || activeAsset?.url || activeAsset?.thumbnailUrl ? (
              <div className="material-layer">
                {activeAsset.type === "video" ? (
                  <video
                    src={activeAsset.previewUrl || activeAsset.url || activeAsset.thumbnailUrl}
                    muted
                    playsInline
                    loop
                    autoPlay={live}
                    controls={!live}
                  />
                ) : (
                  <img
                    src={activeAsset.previewUrl || activeAsset.url || activeAsset.thumbnailUrl}
                    alt={activeAsset.name}
                  />
                )}
              </div>
            ) : null}

            <div className="preview-vignette" />

            <div className="preview-info-card">
              <span>{live ? "当前播放" : "待播放素材"}</span>
              <strong>{activeAsset?.name ?? "暂无可用素材"}</strong>
