                <button
                  type="button"
                  className="gold-button full"
                  onClick={handleStart}
                  disabled={stage === "starting" || readyAssets.length === 0}
                >
                  {stage === "starting" ? "正在准备..." : "开始开播"}
                </button>
              ) : (
                <button
                  type="button"
                  className="danger-button full"
                  onClick={handleStop}
                  disabled={stage === "stopping"}
                >
                  {stage === "stopping" ? "正在结束..." : "停止开播"}
                </button>
              )}
            </div>

            <div className="live-summary">
              <div>
                <span>直播时长</span>
                <strong>{live ? formatDuration(liveSeconds) : "00:00"}</strong>
              </div>
              <div>
                <span>评论数</span>
                <strong>{commentCount}</strong>
              </div>
            </div>
          </div>

          <div className="side-card">
