            <h3>当前素材</h3>

            <div className="current-material">
              <div className="material-thumb">
                {activeAsset?.previewUrl || activeAsset?.url || activeAsset?.thumbnailUrl ? (
                  activeAsset.type === "video" ? (
                    <video
                      src={activeAsset.previewUrl || activeAsset.url || activeAsset.thumbnailUrl}
                      muted
                      playsInline
                    />
                  ) : (
                    <img
                      src={activeAsset.previewUrl || activeAsset.url || activeAsset.thumbnailUrl}
                      alt={activeAsset.name}
                    />
                  )
                ) : (
                  <span>LIVE</span>
                )}
              </div>

              <div>
                <strong>{activeAsset?.name ?? "暂无素材"}</strong>
                <small>
                  {activeAsset?.variants
                    ? `${activeAsset.variants} 个直播版本`
                    : "系统自动生成直播版本"}
                </small>
              </div>
            </div>
          </div>

