                  <button
                    key={item.id}
                    type="button"
                    className={activeAsset?.id === item.id ? "active" : ""}
                    onClick={() => setActiveIndex(index)}
                  >
                    <span>{index + 1}</span>
                    <strong>{item.name}</strong>
                  </button>
                ))}
              </div>
            )}
